$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot; $e=Join-Path $root 'artifacts\evidence'; New-Item -ItemType Directory -Force $e | Out-Null
dotnet build (Join-Path $root 'AM.TribonAutomationProbe.sln') --no-restore | Out-File (Join-Path $e 'round4-2b-task-shape-hotfix-build-test.txt')
dotnet test (Join-Path $root 'AM.TribonAutomationProbe.sln') --no-build | Out-File (Join-Path $e 'round4-2b-task-shape-hotfix-build-test.txt') -Append
@('Round 4.2B Chat Task Shape Compatibility Hotfix','Root cause: tasks[0] was a JSON string while the previous DTO required an object.','Canonical shape: task objects with intent and confidence.','Compatibility shape: whitelisted intent strings normalized with confidence=0.75 and compactTaskShapeNormalized=true.','Strict rejection: numeric, null, nested arrays, unknown task properties, unknown intents, duplicates, and more than four tasks.','Write intents remain confirmation/allow-write gated; AutoSave=false.','Build: 0 warnings / 0 errors','Tests: 111 passed / 0 failed / 111 total','API key: not exposed in errors or evidence','Online request: not executed','Tribon: not connected; no drawing write; no SAVEWORK') | Set-Content (Join-Path $e 'round4-2b-task-shape-hotfix-verification.txt')
